import hashlib
import hmac
import secrets
import threading

try:
    from gateway import GatewayTimeout
except ImportError:  # pragma: no cover
    class GatewayTimeout(Exception):
        pass


_USER_CHARS = set("abcdefghijklmnopqrstuvwxyz0123456789_")


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


class Service:
    def __init__(self, clock, gateway, token_ttl=3600):
        self._clock = clock
        self._gateway = gateway
        self._ttl = token_ttl
        self._lock = threading.RLock()
        self._users = {}        # username -> (salt, hash)
        self._tokens = {}       # token -> (username, created)
        self._docs = {}         # id -> doc dict (internal)
        self._doc_seq = {}      # id -> sequence number
        self._next_seq = 0
        self._cursors = {}      # cursor -> (username, last_seq)
        self._payments = {}     # (user, key) -> payment
        self._payment_order = {}  # user -> [payment]
        self._attempts = {}     # (user, key) -> (reference, amount)
        self._next_attempt = 0
        self._next_payment = 0

    # ---- helpers ----
    @staticmethod
    def _hash(password, salt):
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 5000)

    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if not (self._clock.now() < created + self._ttl):
            del self._tokens[token]
            return None
        return user

    @staticmethod
    def _valid_doc(title, content):
        return (isinstance(title, str) and 1 <= len(title) <= 200
                and isinstance(content, str) and len(content) <= 100000)

    @staticmethod
    def _copy(doc):
        return dict(doc)

    def _user_docs(self, user):
        docs = [d for d in self._docs.values() if d["owner"] == user]
        docs.sort(key=lambda d: self._doc_seq[d["id"]])
        return docs

    def _own(self, user, doc_id):
        if not isinstance(doc_id, str):
            return None
        d = self._docs.get(doc_id)
        if d is None or d["owner"] != user:
            return None
        return d

    # ---- auth ----
    def register(self, username, password):
        with self._lock:
            if not (isinstance(username, str) and 3 <= len(username) <= 32
                    and all(c in _USER_CHARS for c in username)):
                return 400, None
            if not (isinstance(password, str) and len(password) >= 8):
                return 400, None
            if username in self._users:
                return 409, None
            salt = secrets.token_bytes(16)
            self._users[username] = (salt, self._hash(password, salt))
            return 201, None

    def login(self, username, password):
        with self._lock:
            if not isinstance(username, str) or not isinstance(password, str):
                return 401, None
            rec = self._users.get(username)
            if rec is None:
                return 401, None
            salt, h = rec
            if not hmac.compare_digest(h, self._hash(password, salt)):
                return 401, None
            token = secrets.token_hex(24)
            self._tokens[token] = (username, self._clock.now())
            return 200, {"token": token}

    def logout(self, token):
        with self._lock:
            if self._auth(token) is None:
                return 401, None
            del self._tokens[token]
            return 204, None

    # ---- documents ----
    def create_document(self, token, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not self._valid_doc(title, content):
                return 400, None
            self._next_seq += 1
            doc_id = "doc-%d" % self._next_seq
            self._docs[doc_id] = {
                "id": doc_id, "owner": user, "title": title,
                "content": content, "created_at": self._clock.now(),
            }
            self._doc_seq[doc_id] = self._next_seq
            return 201, {"id": doc_id}

    def get_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            d = self._own(user, doc_id)
            if d is None:
                return 404, None
            return 200, self._copy(d)

    def update_document(self, token, doc_id, title, content):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            d = self._own(user, doc_id)
            if d is None:
                return 404, None
            if not self._valid_doc(title, content):
                return 400, None
            d["title"] = title
            d["content"] = content
            return 200, self._copy(d)

    def delete_document(self, token, doc_id):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            d = self._own(user, doc_id)
            if d is None:
                return 404, None
            del self._docs[d["id"]]
            return 204, None

    def list_documents(self, token, page_size=20, cursor=None):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(page_size) or not (1 <= page_size <= 100):
                return 400, None
            last_seq = 0
            if cursor is not None:
                if not isinstance(cursor, str):
                    return 400, None
                entry = self._cursors.get(cursor)
                if entry is None or entry[0] != user:
                    return 400, None
                last_seq = entry[1]
            remaining = [d for d in self._user_docs(user)
                         if self._doc_seq[d["id"]] > last_seq]
            page = remaining[:page_size]
            next_cursor = None
            if len(remaining) > page_size:
                next_cursor = secrets.token_hex(16)
                self._cursors[next_cursor] = (user, self._doc_seq[page[-1]["id"]])
            return 200, {"items": [self._copy(d) for d in page],
                         "next_cursor": next_cursor}

    def search_documents(self, token, query):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not isinstance(query, str) or query == "":
                return 400, None
            q = query.casefold()
            hits = [self._copy(d) for d in self._user_docs(user)
                    if q in d["title"].casefold() or q in d["content"].casefold()]
            return 200, hits

    def export_documents(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [self._copy(d) for d in self._user_docs(user)]

    # ---- payments ----
    def pay(self, token, amount_cents, idempotency_key):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            if not _is_int(amount_cents) or not (1 <= amount_cents <= 1000000):
                return 400, None
            if not isinstance(idempotency_key, str) or idempotency_key == "":
                return 400, None
            k = (user, idempotency_key)
            existing = self._payments.get(k)
            if existing is not None:
                if existing["amount_cents"] == amount_cents:
                    return 200, dict(existing)
                return 409, None
            attempt = self._attempts.get(k)
            if attempt is None:
                self._next_attempt += 1
                attempt = ("pay-ref-%d" % self._next_attempt, amount_cents)
                self._attempts[k] = attempt
            elif attempt[1] != amount_cents:
                return 409, None
            try:
                self._gateway.charge(attempt[0], amount_cents)
            except GatewayTimeout:
                return 504, None
            self._next_payment += 1
            payment = {
                "id": "pay-%d" % self._next_payment,
                "amount_cents": amount_cents,
                "idempotency_key": idempotency_key,
                "created_at": self._clock.now(),
            }
            self._payments[k] = payment
            self._payment_order.setdefault(user, []).append(payment)
            return 201, dict(payment)

    def list_payments(self, token):
        with self._lock:
            user = self._auth(token)
            if user is None:
                return 401, None
            return 200, [dict(p) for p in self._payment_order.get(user, [])]

