        self._users = {}        # username -> (salt, hash)
        self._tokens = {}       # token -> (username, created)
        self._docs = {}         # id -> doc dict (internal)
        self._doc_seq = {}      # id -> sequence number
        self._next_seq = 0
        self._cursors = {}      # cursor -> (username, last_seq)
        self._payments = {}     # (user, key) -> payment
        self._payment_order = {}  # user -> [payment]
        self._attempts = {}     # (user, key) -> (reference, amount)
        self._next_attempt = 0
        self._next_payment = 0

    # ---- helpers ----
    @staticmethod
    def _hash(password, salt):
        return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 5000)

    def _auth(self, token):
        if not isinstance(token, str):
            return None
        entry = self._tokens.get(token)
        if entry is None:
            return None
        user, created = entry
        if not (self._clock.now() < created + self._ttl):
            del self._tokens[token]
            return None
